function fmtD(v){if(!v)return'—';const d=new Date(v);return d.toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'});}
function todayFmt(){return new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'});}
function inr(val) { return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(val); }

