// Renders one page's HTML string into its own offscreen canvas, isolated from all other pages.
async function renderPageToCanvas(html2canvas, pageHtml) {
  const wrapper = document.createElement('div');
  wrapper.style.position = 'fixed';
  wrapper.style.top = '0';
  wrapper.style.left = '-10000px'; // offscreen, not display:none (display:none breaks rendering)
  wrapper.style.zIndex = '-1';
  wrapper.innerHTML = `<style>${PAGE_STYLES}</style>${pageHtml}`;
  document.body.appendChild(wrapper);

  const target = wrapper.querySelector('.pdf-page-inner');
  const canvas = await html2canvas(target, {
    scale: 2,
    useCORS: true,
    width: 794,
    height: 1123,
    windowWidth: 794,
    windowHeight: 1123
  });

  const links = [];
  const aTags = target.querySelectorAll('a[href]');
  const pageRect = target.getBoundingClientRect();
  aTags.forEach(a => {
    const rect = a.getBoundingClientRect();
    const relX = rect.left - pageRect.left;
    const relY = rect.top - pageRect.top;
    
    links.push({
      url: a.getAttribute('href'),
      x: (relX * 210) / 794,
      y: (relY * 297) / 1123,
      w: (rect.width * 210) / 794,
      h: (rect.height * 297) / 1123
    });
  });

  document.body.removeChild(wrapper);
  return { canvas, links };
}

export async function generatePDF(state) {
  const html2pdf = (await import('html2pdf.js')).default;
  const html2canvas = (await import('html2canvas')).default;
  const { jsPDF } = await import('jspdf');

  const { clientName, shootSchedule } = state;

  const hasShoot = shootSchedule && shootSchedule.length > 0 && shootSchedule[0].slotName;
  const quotePage = 1;
  const shootPage = hasShoot ? 2 : null;
  const tcPage1 = hasShoot ? 3 : 2;
  const tcPage2 = tcPage1 + 1;
  const totalPages = tcPage2;

  // Build ordered list of page HTML strings
  const pageHtmls = [
    buildQuotePageHTML(state, quotePage, totalPages, hasShoot)
  ];
  if (hasShoot) {
    pageHtmls.push(buildShootPageHTML(state, shootPage, totalPages));
  }
  pageHtmls.push(buildTCPage1HTML(tcPage1, totalPages));
  pageHtmls.push(buildTCPage2HTML(tcPage2, totalPages));

  // Render each page independently, then assemble into one PDF — no auto-slicing, no stray pages.
  const pdf = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
  const pageWidthMm = 210;
  const pageHeightMm = 297;

  for (let i = 0; i < pageHtmls.length; i++) {
    const { canvas, links } = await renderPageToCanvas(html2canvas, pageHtmls[i]);
    const imgData = canvas.toDataURL('image/jpeg', 0.98);
    if (i > 0) pdf.addPage();
    pdf.addImage(imgData, 'JPEG', 0, 0, pageWidthMm, pageHeightMm);
    links.forEach(l => {
      pdf.link(l.x, l.y, l.w, l.h, { url: l.url });
    });
  }

  pdf.save(`Quotation_${clientName || 'Client'}.pdf`);
}